function pickBy(object, predicate, options) {
      if (object == null) {
        return {};
      }
      var ownOnly = options != null && options.ownOnly === true,
          keys = ownOnly ? getAllKeys(object) : getAllKeysIn(object);
      if (ownOnly) {
        keys = arrayFilter(keys, function(key) {
          return hasOwnProperty.call(object, key);
        });
      }
      var props = arrayMap(keys, function(prop) {
        return [prop];
      });
      predicate = getIteratee(predicate);
      return basePickBy(object, props, function(value, path) {
        return predicate(value, path[0]);
      });
    }

